const chatId = String($json.message?.chat?.id || '');
const text = ($json.message?.text || '').trim();
const m = text.match(/^\/absence\s+(\S+)\s+(\S+)\s+([\s\S]+)/i);

if (!chatId) throw new Error('No chat id in Telegram payload');

if (!m) {
  return {
    json: {
      chatId,
      sendTo: 'REPLACE_SCHOOL_EMAIL@example.com',
      subject: 'Absence notification',
      body: '',
      ackText: 'Usage: /absence <kid> <date> <reason>'
    }
  };
}

const kid = m[1];
const date = m[2];
const reason = m[3].trim();

return {
  json: {
    chatId,
    sendTo: 'REPLACE_SCHOOL_EMAIL@example.com',
    subject: `Absence note - ${kid} - ${date}`,
    body: [
      'Hello,',
      '',
      `Please note that ${kid} will be absent on ${date}.`,
      `Reason: ${reason}.`,
      '',
      'Thank you.'
    ].join('\n'),
    ackText: `Absence note prepared for ${kid} (${date})`
  }
};
